mapper.select:
SELECT NOS.*,(SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code_value = NOS.notice_type and v.code = 'AST008.NOTICE_TYPE')as notice_type_desc FROM ( SELECT pns.NOTICE_ID, pns.BP_ID, pns.TIMES, pns.NOTICE_TYPE, pns.COURIER_COMPANY, pns.TRACKING_NUMBER, pns.SHIPPING_DATE, pns.RECIPIENT, pns.RECIPIENT_CALL, pns.RECIPIENT_ADDRESS, pns.ZIP_CODE, pns.DESCRIPTION, pns.DOCUMENT_TYPE, pns.DOCUMENT_CATEGORY, pns.DOCUMENT_STYLE, pns.BUSINESS_TYPE, pns.CONTRACT_ID, fc.CONTRACT_NUMBER, fc.CONTRACT_NAME, fc.APPROVAL_NUMBER, hbm.BP_NAME, (SELECT MIN(FQC.DUE_DATE) FROM FCT_QUOTATION_CASHFLOW FQC WHERE FQC.CONTRACT_ID=pns.CONTRACT_ID AND FQC.TIMES=PNS.TIMES) DUE_DATE, pns.CREATED_BY FROM PLM_NOTICE_SENT pns LEFT JOIN FCT_CONTRACT fc ON pns.CONTRACT_ID = fc.CONTRACT_ID LEFT JOIN HLS_BP_MASTER hbm ON pns.BP_ID = hbm.BP_ID WHERE fc.DATA_CLASS='NORMAL' AND fc.DOCUMENT_CATEGORY='FCT_CONTRACT' AND fc.DOCUMENT_CATEGORY= pns.DOCUMENT_STYLE
UNION ALL
SELECT pns.NOTICE_ID, pns.BP_ID, pns.TIMES, pns.NOTICE_TYPE, pns.COURIER_COMPANY, pns.TRACKING_NUMBER, pns.SHIPPING_DATE, pns.RECIPIENT, pns.RECIPIENT_CALL, pns.RECIPIENT_ADDRESS, pns.ZIP_CODE, pns.DESCRIPTION, pns.DOCUMENT_TYPE, pns.DOCUMENT_CATEGORY, pns.DOCUMENT_STYLE, pns.BUSINESS_TYPE, pns.CONTRACT_ID, cc.CONTRACT_NUMBER, cc.CONTRACT_NAME, fp.APPROVAL_NUMBER, hbm.BP_NAME, (SELECT MIN(FQC.DUE_DATE) FROM CON_CONTRACT_CASHFLOW FQC WHERE FQC.CONTRACT_ID=pns.CONTRACT_ID AND FQC.TIMES=PNS.TIMES) DUE_DATE, pns.CREATED_BY FROM PLM_NOTICE_SENT pns LEFT JOIN CON_CONTRACT cc ON pns.CONTRACT_ID = cc.CONTRACT_ID LEFT JOIN PRJ_PROJECT fp ON cc.PROJECT_ID = fp.PROJECT_ID LEFT JOIN HLS_BP_MASTER hbm ON pns.BP_ID = hbm.BP_ID WHERE cc.DATA_CLASS='NORMAL' AND cc.DOCUMENT_CATEGORY='CON_CONTRACT' AND cc.DOCUMENT_CATEGORY= pns.DOCUMENT_STYLE ) NOS WHERE 1=1 AND (NOS.CREATED_BY=#{request.userId} OR #{positionCode}='00300' OR #{positionCode}='05500' OR #{request.userId}=10001)
AND NOS.NOTICE_ID = #{noticeId}
AND NOS.NOTICE_TYPE = #{noticeType}
and NOS.BP_NAME like concat(concat('%',#{bpName}),'%')
AND NOS.DUE_DATE >= #{dueDateStart}
AND NOS.DUE_DATE <= #{dueDateEnd}
AND NOS.SHIPPING_DATE >= #{shippingDateStart}
AND NOS.SHIPPING_DATE <= #{shippingDateEnd}
ORDER BY NOS.NOTICE_ID DESC
